import sys

def contains(s, sub):
    """Check if sub is a substring of s"""
    return sub in s

def solve():
    n = int(sys.stdin.readline())
    numbers = [sys.stdin.readline().strip() for _ in range(n)]

    for i, num in enumerate(numbers):
        found = False

        # Try all possible substring lengths from 1 to 9
        for length in range(1, 10):
            # Try all possible starting positions for this length
            for start in range(10 - length):
                candidate = num[start:start + length]

                # Check if this candidate uniquely identifies the number
                unique = True
                for j, other in enumerate(numbers):
                    if i == j:
                        continue
                    if contains(other, candidate):
                        unique = False
                        break

                if unique:
                    print(candidate)
                    found = True
                    break

            if found:
                break

if __name__ == "__main__":
    solve()
"}

