import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    a.sort()

    for i in range(n - 1):
        if a[i] != a[i+1] and a[i] * 2 > a[i+1]:
            print("YES")
            return

    print("NO")

if __name__ == "__main__":
    main()
"}

