messages = []
for _ in range(n):
    parts = input().split()
    sender, receiver, time = parts[0], parts[1], int(parts[2])
    messages.append((sender, receiver, time))

friends = set()

for i, (sender, receiver, t1) in enumerate(messages):
    # Check if this message is a reply to a previous message
    for j in range(i):
        prev_sender, prev_receiver, t2 = messages[j]
        if prev_sender == receiver and prev_receiver == sender:
            if 0 < t1 - t2 <= d:
                friends.add((sender, receiver))
                friends.add((receiver, sender))
                break

print(len(friends))
for pair in sorted(friends):
    print(pair[0], pair[1])
"}

