t = int(input())
for _ in range(t):
    cards = input().strip()

    # Generate all pairs (a, b) such that a * b = 12
    pairs = []
    for a in range(1, 13):
        if 12 % a == 0:
            b = 12 // a
            pairs.append((a, b))

    # Check each pair
    valid_pairs = []
    for a, b in pairs:
        found = False
        # Check each column
        for col in range(1, b + 1):
            all_x = True
            # Check each row in this column
            for row in range(a):
                # Index = column + row*b - 1 (1-indexed to 0-indexed)
                if cards[col + row*b - 1] != 'X':
                    all_x = False
                    break
            if all_x:
                found = True
                break
        if found:
            valid_pairs.append((a, b))

    # Output
    print(len(valid_pairs), end='')
    for a, b in valid_pairs:
        print(f" {a}x{b}", end='')
    print()
"}

