import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Read first line
    n = int(data[0])
    d = int(data[1])

    # Parse messages
    messages = []
    index = 2
    for i in range(n):
        sender = data[index]
        receiver = data[index + 1]
        time = int(data[index + 2])
        messages.append((sender, receiver, time))
        index += 3

    # Find friend pairs
    friends = set()

