def is_perfect_square(x):
    s = int(math.isqrt(x))
    return s * s == x

def solve():
    n, m = map(int, sys.stdin.readline().split())

    # Create a table with 1s
    table = [[1 for _ in range(m)] for _ in range(n)]

    # Adjust the table so that each row and column sum is a perfect square
    for i in range(n):
        for j in range(m):
            # Try to make the row sums perfect squares
            row_sum = sum(table[i])
            if not is_perfect_square(row_sum):
                # Find the smallest number to add to make the row sum a perfect square
                # We need to increase one element in the row
                for k in range(1, 100):
                    new_sum = row_sum + k * k
                    if is_perfect_square(new_sum):
                        # Replace the element at (i, j) with k
                        table[i][j] = k
                        break

    # Now verify columns
    for j in range(m):
        for i in range(n):
            col_sum = sum(table[i][j] for i in range(n))
