def count_distinct_arrangements(gem_colors):
    """Count distinct ways to place gems on a cube considering rotations."""
    from collections import Counter

    freq = Counter(gem_colors)

    if len(freq) == 1:  # All colors are the same
        return 1

    # Total number of distinct arrangements without considering rotations
    total = 1
    for count in freq.values():
        total *= factorial[count]

    # Burnside's Lemma: |X/G| = (1/|G|) * Σ (fix(g) for all g in G)
    # Cube has 24 rotations

    fix = 0

    # Identity rotation (1 rotation): all arrangements
    fix += total

    # 90-degree face rotations (6 faces * 2 directions = 12 rotations)
    # The 4 side faces form 1 cycle of length 4
    # The top/bottom form 2 cycles of length 1 each
    # So we need: 4 of one color, and 1 each of two other colors
    for color1 in freq:
        for color2 in freq:
            for color3 in freq:
                if freq[color1] == 4 and color1 != color2 and color1 != color3 and color2 != color3:
                    fix += total // (factorial[freq[color1]] * factorial[freq[color2]] * factorial[freq[color3]])
    fix *= 2

    # 180-degree face rotations (6 faces = 6 rotations)
    # The 4 side faces form 2 cycles of length 2
    # The top/bottom form 2 cycles of length 1 each
    # So we need: 2 of one color, 2 of another, 1 of two others
    for color1 in freq:
        for color2 in freq:
            for color3 in freq:
                if freq[color1] == 2 and freq[color2] == 2 and len(freq) >= 4:
                    color4 = next(iter(freq - {color1, color2, color3}));
                    fix += total // (factorial[freq[color1]] * factorial[freq[color2]] * factorial[freq[color3]] * factorial[freq[color4]])
    # Also need cases where we have 2, 2, 2, 0 (three colors each with 2)
    for color1 in freq:
        for color2 in freq:
            for color3 in freq:
                if freq[color1] == 2 and freq[color2] == 2 and freq[color3] == 2:
                    fix += total // (factorial[freq[color1]] * factorial[freq[color2]] * factorial[freq[color3]])
    fix *= 6

    # 120-degree corner rotations (8 rotations: 4 corners * 2 directions)
    # The 4 side faces form 1 cycle of length 4
    # The top/bottom form 2 cycles of length 1 each
    # So we need: 4 of one color, and 1 each of two other colors
    for color1 in freq:
        for color2 in freq:
            for color3 in freq:
                if freq[color1] == 4 and color1 != color2 and color1 != color3 and color2 != color3:
                    fix += total // (factorial[freq[color1]] * factorial[freq[color2]] * factorial[freq[color3]])
    fix *= 8

    # 180-degree edge rotations (6 rotations: 6 edges)
    # Faces form 3 cycles of length 2
    # So we need: 2 of each color
    if all(count == 2 for count in freq.values()):
        fix += total // (factorial[2] * factorial[2] * factorial[2])
    fix *= 6

    # Total distinct arrangements
    total_distinct = fix / 24

    return int(total_distinct)

