def solve():
    n = int(input())
    s = input().strip()

    # We'll use dynamic programming
    # dp[i] will represent the maximum pretty set size considering the first i positions
    # where we end with a lowercase letter at position i

    # Initialize dp array with -1 (meaning no valid pretty set ending at this position)
    dp = [-1] * n

    # Try to start at each lowercase letter
    for i in range(n):
        if s[i].islower():
            # Can start at this position
            dp[i] = 1

    # Now build from left to right
    for i in range(n):
        if dp[i] == -1:
            continue

        # Try to extend from position i
        # Find the next position j > i with no uppercase letters between i and j
        # And where s[j] is a lowercase letter not used yet
        for j in range(i + 1, n):
            # Check if there are no uppercase letters between i and j
            has_upper = False
            for k in range(i + 1, j):
                if s[k].isupper():
                    has_upper = True
                    break

            if not has_upper and s[j].islower() and s[j] != s[i]:
                dp[j] = max(dp[j], dp[i] + 1)

    print(max(dp))

solve()
