    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    sizes = list(map(int, data[1:1+n]))

    # Sort the sizes
    sizes.sort()

    # Check all pairs
    found = False
    for i in range(n):
        a = sizes[i]
        max_in_a = (1 << a) - 1  # 2^a - 1
        max_squared = max_in_a * max_in_a

        for j in range(i + 1, n):
            b = sizes[j]

            # Only check if a < b
            if a < b:
                max_in_b = (1 << b) - 1

                if max_squared > max_in_b:
                    found = True
                    break
        if found:
            break

    print("YES" if found else "NO")

if __name__ == "__main__":
    solve()
