def solve():
    n = int(input())
    degree = []
    xor_sum = []

    for _ in range(n):
        d, s = map(int, input().split())
        degree.append(d)
        xor_sum.append(s)

    # We'll try to find edges recursively
    used = [False] * n

    edges = []

    def backtrack(vertex):
        # If all vertices are processed, check if all degrees are satisfied
        if vertex == n:
            # Check if all vertices have the correct degree
            for i in range(n):
                if len([e for e in edges if e[0] == i or e[1] == i]) != degree[i]:
                    return False
            return True

        # Try to find edges from vertex
        for neighbor in range(n):
            if neighbor == vertex or used[neighbor]:
                continue

            # Check if adding this edge makes sense
            # For vertex, we need to check if the XOR makes sense
            if degree[vertex] > 0:
                # If vertex has degree 0, it can't be connected
                if degree[vertex] == 0:
                    continue

                # Check if the XOR of adjacent vertices matches
                current_xor = 0
                for e in edges:
                    if e[0] == vertex:
                        current_xor ^= e[1]
                    if e[1] == vertex:
                        current_xor ^= e[0]

                # After adding this edge, the new XOR should be s[vertex]
                if (current_xor ^ neighbor) != xor_sum[vertex]:
                    continue

            if degree[neighbor] > 0:
                # Check if the XOR for neighbor makes sense
                current_xor = 0
                for e in edges:
                    if e[0] == neighbor:
                        current_xor ^= e[1]
                    if e[1] == neighbor:
                        current_xor ^= e[0]

                # After adding this edge, the new XOR should be s[neighbor]
                if (current_xor ^ vertex) != xor_sum[neighbor]:
                    continue

            # Add the edge and proceed
            edges.append((vertex, neighbor))
            used[neighbor] = True

            if backtrack(vertex + 1):
                return True

            edges.pop()
            used[neighbor] = False

        return False

    if backtrack(0):
        print(len(edges))
        for a, b in edges:
            print(a, b)
    else:
        print(0)

if __name__ == "__main__":
    solve()
