from collections import defaultdict

# Read input
n = int(input())

# Dictionary to store each student's neighbors
students = {}

# Read pairs
for _ in range(n):
    a, b = map(int, input().split())
    students[a] = (a, b)
    students[b] = (a, b)

# Count occurrences of each student
occurrences = defaultdict(int)
for student in students:
    occurrences[student] += 1

# Find first and last students
first = None
last = None

for student, (ai, bi) in students.items():
    if occurrences[student] == 1:
        if ai == 0:
            first = student
        if bi == 0:
            last = student

# Reconstruct the queue
queue = []
current = first
while current is not None:
    queue.append(current)
    # Find next student (one whose ai is current)
    current = None
    for student, (ai, bi) in students.items():
        if ai == current:
            current = student
            break
    # If no next student, break (this shouldn't happen)
    if current is None:
        break

print(' '.join(map(str, queue)))
