# Read pairs
for _ in range(n):
    a, b = map(int, input().split())
    if a not in neighbors:
        neighbors[a] = (a, b)
    else:
        # Update with the second occurrence
        neighbors[a] = (a, b)

# Find the first and last student
first = None
last = None

for student in neighbors:
    if neighbors[student][0] == 0:
        first = student
    if neighbors[student][1] == 0:
        last = student

# Reconstruct the queue
queue = []
