while current is not None:
    queue.append(current)
    # Find next student by looking for the one whose ai is current
    next_student = None
    for s, (ai, bi) in neighbors.items():
        if ai == current:
            next_student = s
            break
    current = next_student

print(' '.join(map(str, queue)))
