    n, m = map(int, input().split())
    grid = [list(input().strip()) for _ in range(n)]

    # Initialize DP table
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1 if grid[0][0] == '.' else 0

    for i in range(n):
        for j in range(m):
            if i == 0 and j == 0:
                continue

            val = 0
            # Check from above (if we moved down)
            if i > 0:
                # Try to move from (i-1, j) to (i, j)
                if grid[i][j] == '.':
                    val = (val + dp[i-1][j]) % MOD
                elif grid[i][j] == 'R':
                    # Rock at (i, j), check if it can be pushed down
                    k = i + 1
                    while k < n and grid[k][j] == 'R':
                        k += 1
                    if k < n and grid[k][j] == '.':
                        val = (val + dp[i-1][j]) % MOD
                        # Push the rock down
                        for p in range(i, k):
                            grid[p][j] = 'R' if p == k else '.'
                        grid[k][j] = 'R'

            # Check from left (if we moved right)
            if j > 0:
                if grid[i][j] == '.':
                    val = (val + dp[i][j-1]) % MOD
                elif grid[i][j] == 'R':
                    # Rock at (i, j), check if it can be pushed right
