def can_cut(s, i):
    """Check if character at position i (1-indexed) can be cut"""
    n = len(s)
    for l in range(1, n):
        if i - l >= 1 and i + l <= n:
            # Check if there are mirrored characters at distance l
            # s[i-l] should equal s[i+l]
            if s[i - l - 1] != s[i + l - 1]:
                continue
            # Check for all k from 1 to l-1
            mirrored = True
            for k in range(1, l):
                # Check s[i-l+k] and s[i+l-k]
                if s[i - l + k - 1] != s[i + l - k - 1]:
                    mirrored = False
                    break
            if mirrored:
                return True
    return False

def grundy_number(s):
    """Calculate Grundy number for string s"""
    if s == "":
        return 0
    n = len(s)
    if n == 1:
        return 0
    # Try all possible cuts
    reachable = set()
    for i in range(1, n + 1):
        if can_cut(s, i):
            # Cut character at position i
            left = s[:i]
            right = s[i + 1:]
            # Grundy number for the new state
            # The middle character is a single character piece
            # The Grundy number for a single character piece is 0
            grundy = grundy_number(left) ^ grundy_number(right)
            reachable.add(grundy)
    # Grundy number is mex of reachable states
    mex = 0
    while mex in reachable:
        mex += 1
    return mex

# Read input
