# Calculate Grundy number
grundy = grundy_number(s)

# Determine winner
if grundy == 0:
    print("Second")
else:
    # Find the minimum winning move
    min_move = 0
    n = len(s)
    for i in range(1, n + 1):
        if can_cut(s, i):
            # Check if this move leads to a win for first player
            left = s[:i]
            right = s[i + 1:]
            # Grundy number for the new state
            grundy = grundy_number(left) ^ grundy_number(right)
            if grundy == 0:
                # This move leads to a losing position for second player
                min_move = i
