                b = 12 // a
                pairs.append((a, b))

        # Sort by increasing a
        pairs.sort()

        # Check each pair
        valid = []
        for a, b in pairs:
            # Check if any column has all 'X'
            all_x = True
            for c in range(b):
                # Check column c
                for i in range(a):
                    pos = c + i * b
                    if cards[pos] != 'X':
