def solve():
    n, m, k = map(int, input().split())

    # flights from city i to Metropolis (0)
    to_metro = [[] for _ in range(n + 1)]
    # flights from Metropolis (0) to city i
    from_metro = [[] for _ in range(n + 1)]

    for _ in range(m):
        d, f, t, c = map(int, input().split())
        if f == 0:
            # flight from Metropolis to city i
            from_metro[t].append((d, c))
        else:
            # flight from city i to Metropolis
            to_metro[f].append((d, c))

    # For each city, find minimum cost to arrive on each day
    arrival_cost = [{} for _ in range(n + 1)]
    for city in range(1, n + 1):
        for day, cost in to_metro[city]:
            arrival_cost[city][day] = min(arrival_cost[city].get(day, float('inf')), cost)

    # For each city, find minimum cost to depart on each day
    departure_cost = [{} for _ in range(n + 1)]
    for city in range(1, n + 1):
        for day, cost in from_metro[city]:
            departure_cost[city][day] = min(departure_cost[city].get(day, float('inf')), cost)

    total_cost = 0

    for city in range(1, n + 1):
        min_total = float('inf')

        # Try all possible arrival days
        for arrival_day, to_cost in arrival_cost[city].items():
            # The earliest return day is arrival_day + k
            earliest_return_day = arrival_day + k

            # Find the cheapest return flight on or after earliest_return_day
            for return_day, from_cost in departure_cost[city].items():
                if return_day >= earliest_return_day:
                    total = to_cost + from_cost
                    if total < min_total:
                        min_total = total

        if min_total == float('inf'):
            print(-1)
            return

        total_cost += min_total

    print(total_cost)

solve()
