import sys

def dijkstra(graph, start, days_limit, n):
    """
    Find minimum cost to reach each node from start within days_limit
    graph is a dictionary mapping from (day, node) to (cost, destination)
    """
    INF = float('inf')
    dist = [[INF] * (n + 1) for _ in range(days_limit + 1)]
    dist[0][start] = 0

    for day in range(days_limit + 1):
        for city in range(n + 1):
            if dist[day][city] < INF:
                # Try to fly on this day
                for edge in graph.get((day, city), []):
                    cost, destination = edge
                    if dist[day + 1][destination] > dist[day][city] + cost:
                        dist[day + 1][destination] = dist[day][city] + cost

    return dist


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))

    # Parse flights
    incoming_flights = {}
    outgoing_flights = {}

    for _ in range(m):
        d = int(next(it))
        f = int(next(it))
        t = int(next(it))
        c = int(next(it))

        if t == 0:
            # Flight to Metropolis (incoming)
            if (d, f) not in incoming_flights:
                incoming_flights[(d, f)] = []
            incoming_flights[(d, f)].append((c, 0))
        else:
            # Flight from Metropolis (outgoing)
            if (d, 0) not in outgoing_flights:
                outgoing_flights[(d, 0)] = []
            outgoing_flights[(d, 0)].append((c, t))

    # For each city, find minimum cost to reach Metropolis by day k
    # and minimum cost to leave Metropolis to return
    min_cost = float('inf')

    # For incoming: start from each city, go to Metropolis
    # For outgoing: start from Metropolis, go to each city

    # Build graph for incoming (to Metropolis)
    graph_in = {}
    for day, city in incoming_flights:
        graph_in[(day, city)] = incoming_flights[(day, city)]

    # Build graph for outgoing (from Metropolis)
    graph_out = {}
    for day, city in outgoing_flights:
        graph_out[(day, 0)] = outgoing_flights[(day, 0)]

    # For each city, find minimum incoming cost by day k
    dist_in = dijkstra(graph_in, start=1, days_limit=k, n=n)

    # For each city, find minimum outgoing cost from day k
    dist_out = dijkstra(graph_out, start=0, days_limit=k, n=n)

    for i in range(1, n + 1):
        # Cost to reach Metropolis by day k
        min_in = INF
        for day in range(k + 1):
            if dist_in[day][i] < min_in:
                min_in = dist_in[day][i]

        # Cost to leave Metropolis from day k to return
        min_out = INF
        for day in range(k, days_limit + 1):
            if dist_out[day][i] < min_out:
                min_out = dist_out[day][i]

        if min_in != INF and min_out != INF:
            min_cost = min(min_cost, min_in + min_out)

    if min_cost == INF:
        print(-1)
    else:
        print(min_cost)

if __name__ == '__main__':
    solve()
