    data = iter(input)

    n = int(next(data))
    m = int(next(data))
    q = int(next(data))

    # Initialize shelves: list of lists of booleans
    shelves = [[False] * m for _ in range(n)]

    # Track the state after each operation
    states = []  # Each element is a list of lists representing the state

    # Also track the count of books after each operation
    book_counts = []

    for op_num in range(1, q + 1):
        op = int(next(data))

        # Store current state before applying operation
        # We'll create a deep copy
        state = [row[:] for row in shelves]
        states.append(state)

        if op == 1:
            # 1 i j - Place a book at position j at shelf i if empty
            i = int(next(data)) - 1  # 0-indexed
            j = int(next(data)) - 1  # 0-indexed
            if shelves[i][j] is False:
                shelves[i][j] = True
        elif op == 2:
            # 2 i j - Remove the book from position j at shelf i if occupied
            i = int(next(data)) - 1  # 0-indexed
            j = int(next(data)) - 1  # 0-indexed
            if shelves[i][j] is True:
                shelves[i][j] = False
        elif op == 3:
            # 3 i - Invert book placing at shelf i
            i = int(next(data)) - 1  # 0-indexed
            for j in range(m):
                shelves[i][j] = not shelves[i][j]
        elif op == 4:
            # 4 k - Return to state after k-th operation
            k = int(next(data))
            # k=0 means initial state
            if k == 0:
                for i in range(n):
                    for j in range(m):
                        shelves[i][j] = False
            else:
                # Restore to state after k-th operation
                # k is 1-indexed
                prev_state = states[k - 1]
                for i in range(n):
                    for j in range(m):
                        shelves[i][j] = prev_state[i][j]
        else:
            raise ValueError(f"Unknown operation: {op}")

        # Count books after this operation
        count = 0
        for i in range(n):
            for j in range(m):
                if shelves[i][j] is True:
                    count += 1
        book_counts.append(count)

    # Output results
    for count in book_counts:
