def solve()
    n = int(input())
    a = list(map(int, input().split()))

    # Sort problems by solving time in descending order
    a.sort(reverse=True)

    m = int(input())
    periods = []
    for _ in range(m):
        l, r = map(int, input().split())
        periods.append((l, r))

    current_time = 0
    period_idx = 0

    for time in a:
        current_time += time

        # Check if current time is within any working period
        while period_idx < len(periods) and current_time > periods[period_idx][1]:
            period_idx += 1

        if period_idx < len(periods) and current_time >= periods[period_idx][0]:
            # Submit immediately
            pass
        else:
            # Wait until the next working period starts
            if period_idx < len(periods):
                current_time = periods[period_idx][0]
            else:
                print(-1)
                return

    # After solving all problems, check if last submission is valid
    if period_idx < len(periods) and current_time >= periods[period_idx][0]:
        print(current_time)
    else:
        print(-1)

