import sys

def solve():
    data = sys.stdin.read().strip().split()
    t = int(data[0])
    results = []

    for i in range(1, t + 1):
        s = data[i]

        # Find all factor pairs (a, b) where a * b = 12
        pairs = []
        for a in range(1, 13):
            if 12 % a == 0:
                b = 12 // a
                pairs.append((a, b))

        # Sort by a (increasing first parameter)
        pairs.sort()

        # Check which pairs are valid
        valid_pairs = []
        for a, b in pairs:
            # Check if any column has all 'X'
            # There are b columns
            # For column j, check positions j, j+b, j+2b, ..., j+(a-1)b
            column_has_all_X = False

            for j in range(b):
                all_X = True
                for k in range(a):
                    if s[j + k * b] != 'X':
                        all_X = False
                        break
                if all_X:
                    column_has_all_X = True
                    break

            if column_has_all_X:
                valid_pairs.append(f"{a}x{b}")

        results.append(f"{len(valid_pairs)} {' '.join(valid_pairs)}")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

