for _ in range(m):
    u, v, color = input().split()
    u = int(u)
    v = int(v)
    edges.append((u, v, color))

# Try to make all edges red
flip_red = set()
for u, v, color in edges:
    if color == 'B':
        flip_red.add(u)
        flip_red.add(v)

# Check if this works
all_red = True
for u, v, color in edges:
    if color == 'R':
        # Edge is red, need to flip both endpoints
        if u not in flip_red or v not in flip_red:
            all_red = False
            break
    else:  # color == 'B'
        # Edge is blue, if we flip both endpoints it becomes red
        if u in flip_red and v in flip_red:
            continue
        else:
            all_red = False
            break

if all_red:
    print(len(flip_red))
    print(' '.join(map(str, sorted(flip_red))))
else:
    # Try to make all edges blue
    flip_blue = set()
    for u, v, color in edges:
        if color == 'R':
            flip_blue.add(u)
            flip_blue.add(v)

    # Check if this works
    all_blue = True
    for u, v, color in edges:
        if color == 'B':
            # Edge is blue, need to flip both endpoints
            if u not in flip_blue or v not in flip_blue:
                all_blue = False
                break
        else:  # color == 'R'
            # Edge is red, if we flip both endpoints it becomes blue
            if u in flip_blue and v in flip_blue:
