def grundy(s, l, r):
    """Return Grundy number for substring s[l:r]."""
    if not moves_possible(s, l, r):
        return 0

    outcomes = set()
    for i in possible_moves(s, l, r):
        left = grundy(s, l, i - 1)
        right = grundy(s, i + 1, r)
        outcomes.add(left ^ right)

    mex = 0
    while mex in outcomes:
        mex += 1
    return mex

# Check if there are any possible moves in substring s[l:r]
def moves_possible(s, l, r):
    for i in range(l, r + 1):
        if i - l < 1 or r - i < 1:
            continue

        # Check for symmetric matches
        # Position i (0-indexed) in the original string
        for d in range(1, min(i - l, r - i) + 1):
            if s[i - d] == s[i + d]:
                return True
    return False

# Find all possible positions where a cut is possible
def possible_moves(s, l, r):
    moves = []
    for i in range(l, r + 1):
        if i - l < 1 or r - i < 1:
            continue

        # Check for symmetric matches
        # Position i (0-indexed) in the original string
        for d in range(1, min(i - l, r - i) + 1):
            if s[i - d] == s[i + d]:
                moves.append(i)
                break
    return moves

s = input().strip()
n = len(s)

# Compute Grundy number for the entire string
grundy_number = grundy(s, 0, n - 1)

if grundy_number == 0:
    print("Second")
else:
    print("First")
    # Find minimal winning move
