    """Check if the union of rectangles exactly matches target_rect"""
    # Check if target_rect contains all given rectangles
    for rect in rectangles:
        if not (rect[0] >= target_rect[0] and rect[1] >= target_rect[1] and
                rect[2] <= target_rect[2] and rect[3] <= target_rect[3]):
            return False

    # Check if target_rect is a square
    if target_rect[2] - target_rect[0] != target_rect[3] - target_rect[1]:
        return False

    # Check if rectangles exactly cover the target_rect without gaps
    covered = set()

    # Mark all points covered by rectangles
    for x1, y1, x2, y2 in rectangles:
        for x in range(x1, x2):
            for y in range(y1, y2):
                covered.add((x, y))

    # Mark all points in target_rect
    for x in range(target_rect[0], target_rect[2]):
        for y in range(target_rect[1], target_rect[3]):
            if (x, y) not in covered:
                return False

    return True

