        rectangles.append((x1, y1, x2, y2))

    # Try all possible combinations of rectangles (subsets)
    for mask in range(1 << n):
        subset_rects = [rectangles[i] for i in range(n) if (mask >> i) & 1]

        # Find bounding rectangle of subset
