    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    s = list(map(int, data[1:1+n]))

    max_count = 0

    # Case 1: keep all 1s
    max_count = max(max_count, s.count(1))

    # Case 2: keep all 0s
    max_count = max(max_count, s.count(0))

    # Case 3: some 1s followed by some 0s
    ones_seen = 0
    for i in range(n):
        if s[i] == 1:
            ones_seen += 1
        else:
            # All previous 1s + all remaining 0s from i onward
            max_count = max(max_count, ones_seen + s[i:].count(0))

    # Case 4: some 0s followed by some 1s
    zeros_seen = 0
    for i in range(n):
        if s[i] == 0:
            zeros_seen += 1
        else:
            # All previous 0s + all remaining 1s from i onward
            max_count = max(max_count, zeros_seen + s[i:].count(1))

