import sys

def solve():
    n, m, k = map(int, sys.stdin.read().split())

    max_area = -1

    # If we make h horizontal cuts and v vertical cuts, we have h+v = k
    # Number of horizontal slices = h+1, number of vertical slices = v+1 = k-h+1
    # Area of each piece = n/(h+1) * m/(v+1)

    # To maximize this, we need to minimize (h+1)*(v+1) = x*y where x+y = k+2
    # The minimum of x*y is at endpoints: x=1 or x=k+1, giving y=k+1
    # So the minimum product is k+1, giving area = nm / (k+1)

    if k >= n * m:
        print(-1)
        return

    # Try the optimal configuration: one direction fully divided, the other untouched
    # If k >= n: we can divide n horizontally, giving (k+1) vertical slices
    if k >= n:
        if m % (k + 1) == 0:
            max_area = n * (m // (k + 1))
    # If k >= m: we can divide m vertically, giving (k+1) horizontal slices
    if k >= m:
        if n % (k + 1) == 0:
            max_area = (n // (k + 1)) * m

    # Try other divisions
    for x in range(1, k + 2):
        if n % x == 0:
            y = k + 2 - x
            if y <= m and m % y == 0:
                area = (n // x) * (m // y)
                max_area = max(max_area, area)

    print(max_area)

solve()
