def is_square_covered(rectangles):
    # Find the bounding box
    min_x = min(r[0] for r in rectangles)
    max_x = max(r[2] for r in rectangles)
    min_y = min(r[1] for r in rectangles)
    max_y = max(r[3] for r in rectangles)

    # Check if the bounding box is a square
    if (max_x - min_x) != (max_y - min_y):
        return False

    # Check if all rectangles are within the bounding box
    for x1, y1, x2, y2 in rectangles:
        if not (min_x <= x1 and x2 <= max_x and min_y <= y1 and y2 <= max_y):
            return False

    # Check if there are no gaps - we can use a grid approach
    # We need to check if every point in the bounding box is covered
    # For a square of side length s, we need to check every (x, y) pair
    # Let's use a set to track covered points

    side_length = max_x - min_x
    covered = set()

    for x1, y1, x2, y2 in rectangles:
        for x in range(x1, x2):
            for y in range(y1, y2):
                covered.add((x, y))

    # Check if all points in the bounding box are covered
    for x in range(min_x, max_x):
        for y in range(min_y, max_y):
            if (x, y) not in covered:
                return False

    return True

