    prefix = [0] * (n + 1)
    for i in range(1, n + 1):
        if types[i - 1] == 1:
            prefix[i] = prefix[i - 1] + problems[i - 1]
        else:
            prefix[i] = prefix[i - 1] - problems[i - 1]

    q = int(input())

    # Process queries
    for _ in range(q):
        l, r = map(int, input().split())
        count = 0

        # Try all possible starting points within [l, r]
        for start in range(l, r + 1):
            # Use a hash map to count occurrences of each difference value
            diff_map = {prefix[start - 1]: 1}
            for end in range(start, r + 1):
                current_diff = prefix[end] - prefix[start - 1]

                if current_diff == k:
                    count += 1

                # Count occurrences of current_diff for future checks
                diff_map[current_diff] = diff_map.get(current_diff, 0) + 1

        print(count)

