import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    # Initialize Fenwick Tree
    max_val = n  # Maximum value in the multiset
    tree = [0] * (max_val + 1)

    def update(i, delta):
        # Update Fenwick Tree at index i
        while i <= max_val:
            tree[i] += delta
            i += i & -i

    def query(i):
        # Query prefix sum up to index i
        res = 0
        while i > 0:
            res += tree[i]
            i -= i & -i
        return res

    # Initial elements
    for _ in range(n):
        val = int(next(it))
        update(val, 1)

    # Process queries
    for _ in range(q):
        k = int(next(it))
        if k > 0:
            # Add element k
            update(k, 1)
        else:
            # Remove |k|-th order statistic
            target_k = abs(k)

            # Find the smallest index i such that prefix sum >= target_k
            low = 1
            high = max_val
            res = max_val + 1  # Invalid index

            while low <= high:
                mid = (low + high) // 2
                prefix = query(mid)
                if prefix >= target_k:
                    res = mid
                    high = mid - 1
                else:
                    low = mid + 1

            if res <= max_val:
                update(res, -1)

    # Find any remaining element
    for i in range(1, max_val + 1):
        if query(i) > 0:
            print(i)
            return

    print(0)

if __name__ == "__main__":
    solve()
