def solve():
    n, m, k = map(int, input().split())
    p = list(map(int, input().split()))

    # Precompute prefix sums for quick range sum queries
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i+1] = prefix[i] + p[i]

    # dp[i][j]: maximum sum using first i elements with j intervals
    dp = [[-1] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(k + 1):
            # Case 1: don't start a new interval at position i
            if dp[i-1][j] != -1:
                dp[i][j] = dp[i-1][j]

            # Case 2: start a new interval at position i (if we have enough space)
            if i >= m and j > 0:
                # The interval starts at i, ends at i+m-1
                # This uses the first i-m elements and j-1 intervals
                if dp[i-m][j-1] != -1:
                    interval_sum = prefix[i] - prefix[i-m]
                    dp[i][j] = max(dp[i][j], dp[i-m][j-1] + interval_sum)

    print(dp[n][k])

solve()
