    s = input().strip()
    t = input().strip()

    # Check if the entire string t can contain s as a subsequence
    if not contains_subsequence(s, t):
        print(0)
        return

    count = 0
    n = len(t)

    # Try each possible cut position
    for i in range(n + 1):
        left = t[:i]
        right = t[i:]

        # Check if both parts contain s as a subsequence
        if contains_subsequence(s, left) and contains_subsequence(s, right):
            count += 1

    print(count)

solve()
