from collections import defaultdict

# Using KMP algorithm
def kmp_failure(pattern):
    failure = [0] * len(pattern)
    for i in range(1, len(pattern)):
        j = failure[i - 1]
        while j > 0 and pattern[i] != pattern[j]:
            j = failure[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
        failure[i] = j
    return failure
def count_occurrences(text, pattern):
    if len(pattern) == 0:
        return 0
    failure = kmp_failure(pattern)
    count = 0
    j = 0
    for i in range(len(text)):
        while j > 0 and text[i] != pattern[j]:
            j = failure[j - 1]
        if text[i] == pattern[j]:
            j += 1
        if j == len(pattern):
            count += 1
            j = failure[j - 1]
    return count

# Count occurrences of each individual string
single_occurrences = defaultdict(int)
for s in strings:
    single_occurrences[s] = count_occurrences(t, s)

# Now count occurrences of each concatenation
