# Count occurrences of each concatenated pair
for i in range(n):
    for j in range(n):
        concatenated = strings[i] + strings[j]
        counts[concatenated] += 1

# Calculate the sum
result = 0
for pattern, occurrence_count in counts.items():
    if pattern in single_occurrences:
        result += occurrence_count * single_occurrences[pattern]

print(result)
