rectangles = []
min_x = float('inf')
max_x = float('-inf')
min_y = float('inf')
max_y = float('-inf')

for _ in range(n):
    x1, y1, x2, y2 = map(int, input().split())
    rectangles.append((x1, y1, x2, y2))
    min_x = min(min_x, x1)
    max_x = max(max_x, x2)
    min_y = min(min_y, y1)
    max_y = max(max_y, y2)

# Check if bounding box is a square
if max_x - min_x != max_y - min_y:
    print("NO")
else:
    # Check if every point in bounding box is covered
    covered = set()
    for x1, y1, x2, y2 in rectangles:
        for x in range(x1, x2):
            for y in range(y1, y2):
                covered.add((x, y))

    # Check if all points in bounding box are covered
    all_covered = True
    for x in range(min_x, max_x):
        for y in range(min_y, max_y):
            if (x, y) not in covered:
                all_covered = False
                break
        if not all_covered:
            break

    print("YES" if all_covered else "NO")
