import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Strategy: flip signs in a zigzag pattern
        # Keep even-indexed elements as is, flip odd-indexed elements
        b = []
        for i in range(n):
            if i % 2 == 0:
                b.append(a[i])
            else:
                b.append(-a[i])

        out_lines.append(' '.join(map(str, b)))

    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
