import sys

def solve():
    MOD = 10**9 + 7

    # Read input
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Parse input
    n = int(data[0])
    m = int(data[1])

    # Read grid
    grid = []
    idx = 2
    for i in range(n):
        row = data[idx:idx+m]
        grid.append(row)
        idx += m

    # DP table: dp[i][j] = number of ways to reach (i, j)
    dp = [[0] * m for _ in range(n)]

    # Starting position (1-indexed)
    dp[0][0] = 1

    # Fill DP table
    for i in range(n):
        for j in range(m):
            if dp[i][j] == 0:
                continue

            # Move down to (i+1, j)
            if i + 1 < n:
                if grid[i+1][j] == '.':
                    dp[i+1][j] = (dp[i+1][j] + dp[i][j]) % MOD
                elif grid[i+1][j] == 'R':
                    # Check if we can push the rock further down
                    if i + 2 < n and grid[i+2][j] == '.':
                        # The rock at (i+1, j) moves to (i+2, j)
                        # So we can move to (i+1, j) with the rock pushing
                        dp[i+1][j] = (dp[i+1][j] + dp[i][j]) % MOD

            # Move right to (i, j+1)
            if j + 1 < m:
                if grid[i][j+1] == '.':
                    dp[i][j+1] = (dp[i][j+1] + dp[i][j]) % MOD
                elif grid[i][j+1] == 'R':
                    # Check if we can push the rock further right
                    if j + 2 < m and grid[i][j+2] == '.':
                        # The rock at (i, j+1) moves to (i, j+2)
                        # So we can move to (i, j+1) with the rock pushing
                        dp[i][j+1] = (dp[i][j+1] + dp[i][j]) % MOD

    print(dp[n-1][m-1])

if __name__ == "__main__":
    solve()
