n = int(input())
roads = []

for _ in range(n):
    a, b, c = map(int, input().split())
    roads.append((a, b, c))

# Build adjacency list
graph = {i: [] for i in range(1, n+1)}
for a, b, c in roads:
    graph[a].append((b, c))
    graph[b].append((a, c))  # For undirected graph

# Check if we can form a clockwise cycle (1→2→3→1)
clockwise_cost = 0
for i in range(n):
    current_city = i + 1
    next_city = (i + 2) % n + 1  # next city in clockwise order

    # Find the road from current_city to next_city
    found = False
    for neighbor, cost in graph[current_city]:
        if neighbor == next_city:
            found = True
            break

    if not found:
        # We need to reverse a road connected to current_city
        # Find which road to reverse
        for neighbor, cost in graph[current_city]:
            if neighbor != next_city:
                # Reverse this road
                clockwise_cost += cost
                found = True
                break
        if not found:
            clockwise_cost = float('inf')
            break

# Check if we can form a counterclockwise cycle (2→1, 3→2, 1→3)
counterclockwise_cost = 0
for i in range(n):
    current_city = i + 1
    prev_city = (i + 1) % n + 1  # previous city in counterclockwise order

    # Find the road from prev_city to current_city
    found = False
    for neighbor, cost in graph[prev_city]:
        if neighbor == current_city:
            found = True
            break

    if not found:
        # We need to reverse a road connected to prev_city
        for neighbor, cost in graph[prev_city]:
            if neighbor != current_city:
                counterclockwise_cost += cost
                found = True
                break
        if not found:
            counterclockwise_cost = float('inf')
            break

print(min(clockwise_cost, counterclockwise_cost))
