def solve():
    n, q = map(int, input().split())
    cnt = list(map(int, input().split()))

    for _ in range(q):
        parts = input().split()
        if parts[0] == '1':
            # Update cnt[pos] to val
            pos = int(parts[1])
            val = int(parts[2])
            cnt[pos] = val
        else:
            # Query: x and k
            x = int(parts[1])
            k = int(parts[2])

            # Calculate total elements <= 2^x after splitting
            # cnt[i] elements of value 2^i
            # For i <= x: contributes cnt[i] elements, costs 0 operations
            # For i > x: contributes cnt[i] elements, costs (i - x) * cnt[i] operations
            total = 0
            operations = 0

            for i in range(n):
                if i <= x:
                    total += cnt[i]
                else:
                    total += cnt[i]
                    operations += (i - x) * cnt[i]

            if total >= k:
                print(operations)
            else:
                print(-1)

solve()
