import sys

def solve():
    data = sys.stdin.read().strip().split('\n')
    t = int(data[0])
    tests = data[1:t+1]

    for test in tests:
        # Check all possible (a, b) pairs
        results = []

        # 1x12: check if all 12 cards are 'X'
        if all(card == 'X' for card in test):
            results.append((1, 12))

        # 2x6: check if any column (0-5) has both cards as 'X'
        for col in range(6):
            if test[col] == 'X' and test[col + 6] == 'X':
                results.append((2, 6))
                break

        # 3x4: check if any column (0-3) has all 3 cards as 'X'
        for col in range(4):
            if test[col] == 'X' and test[col + 4] == 'X' and test[col + 8] == 'X':
                results.append((3, 4))
                break

        # 4x3: check if any column (0-2) has all 4 cards as 'X'
        for col in range(3):
            if test[col] == 'X' and test[col + 3] == 'X' and test[col + 6] == 'X' and test[col + 9] == 'X':
                results.append((4, 3))
                break

        # 6x2: check if any column (0-1) has both cards as 'X'
        for col in range(2):
            if test[col] == 'X' and test[col + 2] == 'X':
                results.append((6, 2))
                break

        # 12x1: check if any card is 'X'
        if any(card == 'X' for card in test):
            results.append((12, 1))

        # Sort by a, then by b
        results.sort(key=lambda x: (x[0], x[1]))

        # Format output
        output = f"{len(results)}"
        for a, b in results:
            output += f" {a}x{b}"
        print(output)

if __name__ == "__main__":
    solve()
