import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    a = data[2]
    b = data[3]
    s = data[4]

    # Find all positions where a matches the start of s
    start_positions = []
    for i in range(n - len(s) + 1):
        if a[i:i+len(s)] == s[:len(s)]:
            start_positions.append(i)

    # Find all positions where b matches the end of s
    end_positions = []
    for i in range(len(s), n + 1):
        if b[i-len(s):i] == s[len(s)-1:]:
            end_positions.append(i)

    # Count valid pairs
    count = 0
    for start in start_positions:
        for end in end_positions:
            # Check if they overlap
            if start <= end and end - len(s) + 1 <= start:
                count += 1

    print(count)

if __name__ == "__main__":
    solve()
"}

