periods = []
for _ in range(m):
    l, r = map(int, input().split())
    periods.append((l, r))

# Sort by solving time (shortest first)
solving_times.sort()

# Find the earliest period that starts >= given time
# If no such period exists, return -1

def find_period(start):
    for l, r in periods:
        if l >= start:
            return l  # Start waiting at the beginning of this period
    return -1  # No period available


current_time = 0
for time in solving_times:
    current_time += time
    # Check if we can submit immediately (within some period)
    for l, r in periods:
        if l <= current_time <= r:
            break
    else:
        # Not in any period, need to wait
        period_start = find_period(current_time)
        if period_start == -1:
            print(-1)
            exit()
        current_time = period_start

