    for _ in range(n):
        name = input().strip()
        names.append(name)

    # dp[i][start][end] = maximum total length of dynasty ending at position i with start and end
    dp = [{} for _ in range(n)]

    for i in range(n):
        name = names[i]
        start = name[0]
        end = name[-1]
        length = len(name)

        # Start a new dynasty with this name
        dp[i][(start, end)] = length

        # Extend from previous dynasties that end with 'start'
        for j in range(i):
            for (prev_start, prev_end) in dp[j]:
                if prev_end == start:
                    total = dp[j][(prev_start, prev_end)] + length
                    if (start, end) in dp[i] or dp[i][(start, end)] < total:
                        dp[i][(start, end)] = total

    # Find the maximum dynasty where start == end
    max_length = 0
    for i in range(n):
        for (s, e) in dp[i]:
            if s == e:
                if dp[i][(s, e)] > max_length:
                    max_length = dp[i][(s, e)]

    print(max_length)

