n, m, q = map(int, input().split())

# Initialize bookcase: True = book, False = empty
bookcase = [False] * n
for i in range(n):
    bookcase[i] = [False] * m

# Store states after each operation (0-indexed)
# states[0] = initial state (0 operations applied)
states = []
states.append([row[:] for row in bookcase])  # Initial state

for op_num in range(1, q + 1):
    parts = input().split()
    if parts[0] == '1':
        i = int(parts[1]) - 1
        j = int(parts[2]) - 1
        if not bookcase[i][j]:
            bookcase[i][j] = True
    elif parts[0] == '2':
        i = int(parts[1]) - 1
        j = int(parts[2]) - 1
        if bookcase[i][j]:
            bookcase[i][j] = False
    elif parts[0] == '3':
        i = int(parts[1]) - 1
        for j in range(m):
            bookcase[i][j] = not bookcase[i][j]
    elif parts[0] == '4':
        k = int(parts[1])
        # Revert to state after operation k
        bookcase = [row[:] for row in states[k]]

    # Count books in current state
    count = 0
    for i in range(n):
        for j in range(m):
            if bookcase[i][j]:
                count += 1
    print(count)

    # Store current state
    states.append([row[:] for row in bookcase])
