# List to store all states after each operation
states = []

total_books = 0

# Helper function to apply operation
def apply_operation(op_type, i, j, shelves, total_books):
    if op_type == 1:  # Place book
        if j not in shelves[i]:
            shelves[i].add(j)
            total_books += 1
    elif op_type == 2:  # Remove book
        if j in shelves[i]:
            shelves[i].remove(j)
            total_books -= 1
    elif op_type == 3:  # Invert shelf
        for pos in range(m):
            if pos in shelves[i]:
                shelves[i].remove(pos)
                total_books -= 1
            else:
                shelves[i].add(pos)
                total_books += 1
    return total_books

for op_num in range(1, q + 1):
    # Read operation
    parts = input().split()
    op_type = int(parts[0])

    if op_type == 1 or op_type == 2 or op_type == 3:
        i = int(parts[1]) - 1  # 0-indexed
        j = int(parts[2]) - 1

    elif op_type == 4:
        k = int(parts[1])

    # Store current state before applying operation
    states.append([shelf.copy() for shelf in shelves])

    if op_type == 1 or op_type == 2 or op_type == 3:
        total_books = apply_operation(op_type, i, j, shelves, total_books)
    elif op_type == 4:
        k = int(parts[1])
        if k == 0:
            # Return to initial state (all empty)
            for shelf in shelves:
                shelf.clear()
        else:
            # Return to state after k-th operation
            # states are 0-indexed, so k-1 gives the state
            for i in range(n):
                shelves[i].clear()
                shelves[i].update(states[k-1][i])

    # Output total books
    print(total_books)
