def solve(n, m, k):
    # dp[a][b][k] = minimum cost to get k squares from a bar of size a x b
    dp = [[[float('inf')] * (n * m + 1) for _ in range(m + 1)] for _ in range(n + 1)]

    # Base cases: we need all squares or no squares, cost is 0
    for a in range(n + 1):
        for b in range(m + 1):
            dp[a][b][0] = 0
            dp[a][b][a * b] = 0

    # Fill DP table
    for a in range(1, n + 1):
        for b in range(1, m + 1):
            for k in range(1, a * b):
                # Try all horizontal breaks
                for i in range(1, a):
                    # Break horizontally into i x b and (a-i) x b
                    # Try all ways to split k between the two pieces
                    for split_k in range(1, k):
                        cost = b * b + dp[i][b][split_k] + dp[a - i][b][k - split_k]
                        if cost < dp[a][b][k]:
                            dp[a][b][k] = cost

                # Try all vertical breaks
                for j in range(1, b):
                    # Break vertically into a x j and a x (b-j)
                    # Try all ways to split k between the two pieces
                    for split_k in range(1, k):
                        cost = a * a + dp[a][j][split_k] + dp[a][b - j][k - split_k]
                        if cost < dp[a][b][k]:
                            dp[a][b][k] = cost

    return dp[n][m][k]

