    parent = [-1] * n
    depth = [0] * n

    stack = [(start, -1)]

    while stack:
        node, prev = stack.pop()
        if visited[node]:
            continue
        visited[node] = True

        # Check if we've returned to start and created a cycle
        if node == start and prev != -1:
            # We've completed a cycle from start to start
            if (depth[node] - depth[prev]) % 2 == 1:
                # The cycle length is odd
                return True
            else:
                # The cycle length is even
                return False

        # Depth of node is depth of parent + 1
        depth[node] = depth[prev] + 1 if prev != -1 else 0

        # Push all neighbors
