def count_occurrences(t, s):
    if len(s) > len(t):
        return 0

    # Concatenate t + '#' + s
    temp = t + '#' + s
    n = len(temp)

    # Compute Z-array
    Z = [0] * n
    l, r = 0, 0

    for i in range(1, n):
        if i <= r:
            Z[i] = min(r - i + 1, Z[i - l])

        while i + Z[i] < n and temp[Z[i]] == temp[i + Z[i]]:
            Z[i] += 1

        if i + Z[i] - 1 > r:
            l = i
            r = i + Z[i] - 1

    return sum(1 for z in Z if z == len(s))

