def solve():
    N = int(input())
    prices = list(map(int, input().split()))

    # Buy on day i if price is less than next day's price (local minimum)
    # Sell on day i if price is greater than previous day's price (local maximum)
    profit = 0

    for i in range(N):
        # Buy condition: price[i] < price[i+1] (except for the last day)
        if i < N - 1 and prices[i] < prices[i + 1]:
            # Buy share at prices[i]
            profit -= prices[i]

        # Sell condition: price[i] > price[i-1] (except for the first day)
        if i > 0 and prices[i] > prices[i - 1]:
            # Sell share at prices[i]
            profit += prices[i]

    print(profit)

if __name__ == "__main__":
