import sys

def count_lucky_digits(n):
    """Count the number of 4s and 7s in the decimal representation of n"""
    return str(n).count('4') + str(n).count('7')

def solve():
    n = int(sys.stdin.readline().strip())

    # Count how many numbers have each possible lucky digit score
    max_score = 0
    count = {}
    for i in range(1, n + 1):
        s = count_lucky_digits(i)
        count[s] = count.get(s, 0) + 1
        if s > max_score:
            max_score = s

    # Total number of ways to choose 7 distinct numbers and assign to parties
    total = 1
    for i in range(n, n - 7, -1):
        total *= i
    total %= (10**9 + 7)

    # DP: dp[i][j] = number of ways to choose i numbers with total score j
    dp = [{} for _ in range(8)]
    dp[0][0] = 1

    for i in range(1, 8):
        for score in dp[i - 1]:
            for s in count:
                dp[i][score + s] = dp[i].get(score + s, 0) + dp[i - 1][score] * count[s]

    # For each possible score of the LEP, count valid assignments
    answer = 0
    for s_lep in range(max_score + 1):
        if count.get(s_lep, 0) == 0:
            continue

        # Number of ways to choose 6 other numbers with total score < s_lep
        for total_score in dp[6]:
            if total_score < s_lep:
                answer += count[s_lep] * dp[6][total_score]
        answer %= (10**9 + 7)

    print(answer)

if __name__ == "__main__":
    solve()
"}

