def main():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    # Read initial elements
    elements = []
    for _ in range(n):
        elements.append(int(next(it)))

    # Maintain a sorted list of values
    sorted_vals = sorted(set(elements))
    count_map = {val: elements.count(val) for val in sorted_vals}

    # Maintain a list of tuples (value, count) in sorted order
    # We'll keep a list that we can binary search
    # Actually, let's keep a list that we can insert into
    sorted_list = sorted_vals
    count_map = {val: elements.count(val) for val in sorted_list}

    def get_size():
        return sum(count_map.values())

    def find_kth(k):
        # Find the k-th element using binary search
        left, right = 0, len(sorted_list) - 1
        while left < right:
            mid = (left + right) // 2
            if k <= sum(count_map[val] for val in sorted_list[:mid+1]):
                right = mid
            else:
                left = mid + 1

        # Found the value at position left
        return left

    def remove_kth(k):
        idx = find_kth(k)
        val = sorted_list[idx]
        count_map[val] -= 1
        if count_map[val] == 0:
            del count_map[val]
            # Remove from sorted_list
            sorted_list.pop(idx)

