import sys

def is_subsequence(s, t):
    """Check if s is a subsequence of t"""
    if not s:
        return True
    if not t:
        return False

    s_index = 0
    for char in t:
        if s_index < len(s) and char == s[s_index]:
            s_index += 1

    return s_index == len(s)

def solve() -> None:
    s = sys.stdin.readline().strip()
    t = sys.stdin.readline().strip()

    count = 0
    len_s = len(s)
    len_t = len(t)

    for i in range(len_t):
        left = t[:i]
        right = t[i:]

        if len(left) >= len_s and len(right) >= len_s:
            # Check if both parts contain s as a subsequence
            if is_subsequence(s, left) and is_subsequence(s, right):
                count += 1

    print(count)

if __name__ == "__main__":
    solve()
"}

