def count_occasions(n, a, b):
    """Count how many pairs (l, r) satisfy max(a[l..r]) == min(b[l..r])."""

    # Precompute maximums for all subarrays starting at each position
    max_a = [0] * n
    for i in range(n):
        max_val = a[i]
        for j in range(i, n):
            max_val = max(max_val, a[j])
            max_a[j] = max_val

    # Precompute minimums for all subarrays starting at each position
    min_b = [0] * n
    for i in range(n):
        min_val = b[i]
        for j in range(i, n):
            min_val = min(min_val, b[j])
            min_b[j] = min_val

    # Count matching positions
    count = 0
    for i in range(n):
        for j in range(i, n):
            if max_a[i] == min_b[i]:
                count += 1

    return count

